mod solver;
use clap::Parser;
use colog::default_builder;
use enigma::Enigma;
use log::{LevelFilter, error};
use solver::EnigmaSolver;

use crate::commands::{Cli, TestArgs};
mod commands;

fn main() {
    let mut builder = default_builder();
    let cli = Cli::parse();
    if cli.debug {
        builder.filter(None, LevelFilter::Debug);
    };

    builder.init();

    match cli.command {
        commands::Commands::Test(test_args) => run_test(test_args),
    }
}

fn run_test(args: TestArgs) {
    match (args.easy, args.hard) {
        (true, true) => error!("Must choose either 'easy' or 'hard'."),
        (true, false) => solve_easy(),
        (false, true) => solve_hard(),
        (false, false) => panic!("Unreachable"),
    }
}

fn solve_easy() {
    let plain_part = "";
    let cipher = "";

    let solver = EnigmaSolver::new(cipher, plain_part);
    let settings = solver.known_plain_text_cipher_break();

    let Some(settings) = settings else {
        error!("Unable to break cipher!!!");
        return;
    };

    println!("Enigma Settings Solution: {settings:#?}");
    println!(
        "Deciphered text: {}",
        Enigma::from(settings).encrypt_str(cipher).unwrap()
    )
}

fn solve_hard() {
    let plain_part = "";
    let cipher = "";

    let solver = EnigmaSolver::new(cipher, plain_part);
    let settings = solver.known_plain_text_cipher_break();

    let Some(settings) = settings else {
        error!("Unable to break cipher!!!");
        return;
    };

    println!("Enigma Settings Solution: {settings:#?}");
    println!(
        "Deciphered text: {}",
        Enigma::from(settings).encrypt_str(cipher).unwrap()
    )
}
